async function yourFunction(input) {
  const data = input.data || {};
  const filteredData = Object.fromEntries(
    Object.entries(data)
      .filter(([key]) => key !== "hs_email_domain")
      .map(([key, value]) => {
        if (key === "recent_1_star_review_date" && value) {
          const dateValue = new Date(value);
          if (!isNaN(dateValue.getTime())) {
            return [key, dateValue.getTime()];
          }
        }
        return [key, value];
      })
  );
  return { properties: filteredData };
}

